// WooCommerce sends the full order object as the webhook body.
// n8n makes the parsed JSON directly available as $input.first().json
const order = $input.first().json;
const lineItem = order.line_items && order.line_items[0];

if (!lineItem) {
  throw new Error('No line items found in order #' + order.id);
}

return [{
  json: {
    order_id:            order.id,
    order_status:        order.status,
    order_date:          order.date_created,
    customer_email:      order.billing.email,
    customer_name:       order.billing.first_name + ' ' + order.billing.last_name,
    customer_first_name: order.billing.first_name,
    product_id:          String(lineItem.product_id),
    product_name:        lineItem.name,
    quantity:            lineItem.quantity,
    total:               order.total,
    currency:            order.currency || 'USD'
  }
}];

// Pull order context from earlier node
const orderData = $('Code - Parse Order Data').first().json;
const productId  = String(orderData.product_id);

// All key rows were aggregated into a single item
const allKeys = $input.first().json.all_keys || [];

// Find the first key that matches product + status = available
const match = allKeys.find(row =>
  String(row.product_id) === productId &&
  String(row.status).toLowerCase() === 'available'
);

if (!match) {
  return [{
    json: {
      ...orderData,
      key_found:   false,
      license_key: null,
      sheet_row:   null
    }
  }];
}

return [{
  json: {
    ...orderData,
    key_found:   true,
    license_key: match.license_key,
    sheet_row:   match.row_number
  }
}];

const d   = $input.first().json;
const now = new Date().toLocaleDateString('en-US', {
  year: 'numeric', month: 'long', day: 'numeric'
});

const html = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body{font-family:Arial,sans-serif;margin:0;padding:0;background:#f1f5f9}
    .wrap{max-width:600px;margin:30px auto;background:#fff;border-radius:10px;overflow:hidden;box-shadow:0 4px 20px rgba(0,0,0,.08)}
    .hdr{background:linear-gradient(135deg,#1e40af,#2563eb);padding:32px 40px;text-align:center;color:#fff}
    .hdr h1{margin:0;font-size:24px;font-weight:700;letter-spacing:-.3px}
    .hdr p{margin:8px 0 0;opacity:.85;font-size:14px}
    .body{padding:36px 40px}
    .badge{background:#f0f9ff;border:1px solid #bae6fd;border-radius:6px;padding:10px 18px;display:inline-block;margin-bottom:22px;color:#0369a1;font-weight:600;font-size:13px}
    .prod{font-size:20px;font-weight:700;color:#1e293b;margin:0 0 18px}
    .key-lbl{font-size:11px;color:#64748b;font-weight:700;text-transform:uppercase;letter-spacing:1.2px;margin-bottom:8px}
    .key-box{background:#0f172a;color:#4ade80;font-family:'Courier New',monospace;font-size:22px;font-weight:700;padding:24px;text-align:center;border-radius:8px;letter-spacing:4px;margin-bottom:28px;word-break:break-all}
    .steps{background:#f8fafc;border-radius:8px;padding:22px 24px;margin-bottom:28px}
    .steps h3{margin:0 0 12px;font-size:15px;color:#1e293b}
    .steps ol{margin:0;padding-left:20px;color:#475569;font-size:14px;line-height:1.9}
    .note{border-left:3px solid #2563eb;padding:12px 16px;background:#f0f9ff;border-radius:0 6px 6px 0;font-size:14px;color:#1e40af;margin-bottom:24px}
    .ftr{background:#f8fafc;padding:18px 40px;text-align:center;font-size:12px;color:#94a3b8;border-top:1px solid #e2e8f0}
  </style>
</head>
<body>
  <div class="wrap">
    <div class="hdr">
      <h1>Your Product is Ready!</h1>
      <p>Thank you for your purchase — your license key is below</p>
    </div>
    <div class="body">
      <p style="font-size:16px;color:#1e293b;margin-bottom:20px">Hi <strong>${d.customer_first_name}</strong>,</p>
      <p style="color:#475569;font-size:15px;margin-bottom:22px">Your payment was confirmed and your order has been processed. Here is everything you need to get started right away.</p>
      <div class="badge">Order #${d.order_id}&nbsp;&nbsp;|&nbsp;&nbsp;${now}</div>
      <p class="prod">${d.product_name}</p>
      <div class="key-lbl">Your License Key</div>
      <div class="key-box">${d.license_key}</div>
      <div class="steps">
        <h3>How to Activate</h3>
        <ol>
          <li>Download the installer from your account dashboard</li>
          <li>Install the software on your device</li>
          <li>Open the app and navigate to <strong>Help &rarr; Activate License</strong></li>
          <li>Paste your license key and click <strong>Activate</strong></li>
        </ol>
      </div>
      <div class="note">Need help? Simply reply to this email and our support team will respond within 24 hours.</div>
      <p style="color:#475569;font-size:14px">Best regards,<br><strong>Support Team</strong></p>
    </div>
    <div class="ftr">
      <p>Order #${d.order_id} &bull; Sent to ${d.customer_email}</p>
      <p>Please keep your license key in a safe place.</p>
    </div>
  </div>
</body>
</html>`;

return [{
  json: {
    ...d,
    email_html:    html,
    email_subject: 'Your License Key — Order #' + d.order_id + ' (' + d.product_name + ')'
  }
}];
